<?php $base='/saves/'.(int)$context->saveId().'/matches/'.(int)$fixture['id'];$status=$state['status']??$fixture['status'];$homeScore=$state['home_score']??($fixture['home_score']??0);$awayScore=$state['away_score']??($fixture['away_score']??0);$stats=$state['stats']??['home'=>['possession'=>0,'shots'=>0,'on_target'=>0,'fouls'=>0,'yellow'=>0,'red'=>0],'away'=>['possession'=>0,'shots'=>0,'on_target'=>0,'fouls'=>0,'yellow'=>0,'red'=>0]];$userSide=$state['sides'][$side]??null; ?>
<div id="match-root" data-status="<?= e($status) ?>" data-step-url="<?= $base ?>/step" data-resume-url="<?= $base ?>/resume">
<div class="match-header"><span class="eyebrow">Journée <?= (int)$fixture['matchday'] ?> · <?= format_date($fixture['scheduled_at'],'d/m/Y H:i') ?></span><div class="scoreboard"><div><span class="club-crest club-crest--large" style="--crest:<?= e($fixture['home_color']) ?>"><?= e($fixture['home_short']) ?></span><h1><?= e($fixture['home_name']) ?></h1></div><div class="scoreboard__score"><strong id="home-score"><?= (int)$homeScore ?></strong><span>–</span><strong id="away-score"><?= (int)$awayScore ?></strong><small id="match-minute"><?= $status==='scheduled'?'Avant-match':($status==='finished'?'Terminé':(int)($state['minute']??0).'′') ?></small></div><div><span class="club-crest club-crest--large" style="--crest:<?= e($fixture['away_color']) ?>"><?= e($fixture['away_short']) ?></span><h1><?= e($fixture['away_name']) ?></h1></div></div></div>
<?php if($status==='scheduled'): ?><section class="panel match-start"><div class="panel__body"><h2>Le vestiaire vous attend</h2><p>Vérifiez votre tactique avant le coup d’envoi. Le match se déroule minute par minute.</p><a class="btn btn--ghost" href="/saves/<?= (int)$context->saveId() ?>/tactics">Voir la tactique</a><form method="post" action="<?= $base ?>/start"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="btn btn--primary">Coup d’envoi</button></form></div></section><?php else: ?>
<div class="match-controls"><button class="btn btn--primary" id="match-step" <?= $status==='finished'||$status==='halftime'?'disabled':'' ?>>Jouer 1 minute</button><button class="btn btn--ghost" id="match-auto" <?= $status==='finished'||$status==='halftime'?'disabled':'' ?>>▶ Lecture auto</button><form id="resume-form" class="inline-form <?= $status==='halftime'?'':'is-hidden' ?>"><button class="btn btn--primary">Reprendre la seconde période</button></form><span class="badge" id="match-status-badge"><?= e($status) ?></span></div><?php endif; ?>
<div class="match-grid"><section class="panel"><div class="panel__header"><h2>Commentaires en direct</h2></div><div class="panel__body"><div class="commentary" id="match-events"><?php foreach($events as $event): ?><div class="commentary__item commentary__item--<?= e($event['type']) ?>"><span><?= (int)$event['minute'] ?>′</span><p><?= e($event['description']) ?></p></div><?php endforeach; ?></div></div></section>
<aside><section class="panel"><div class="panel__header"><h2>Statistiques</h2></div><div class="panel__body match-stats" id="match-stats"><?php $totalPoss=max(1,$stats['home']['possession']+$stats['away']['possession']); ?><div><span id="home-possession"><?= round($stats['home']['possession']*100/$totalPoss) ?>%</span><label>Possession</label><span id="away-possession"><?= round($stats['away']['possession']*100/$totalPoss) ?>%</span></div><div><span id="home-shots"><?= (int)$stats['home']['shots'] ?></span><label>Tirs</label><span id="away-shots"><?= (int)$stats['away']['shots'] ?></span></div><div><span id="home-on-target"><?= (int)$stats['home']['on_target'] ?></span><label>Tirs cadrés</label><span id="away-on-target"><?= (int)$stats['away']['on_target'] ?></span></div><div><span id="home-fouls"><?= (int)$stats['home']['fouls'] ?></span><label>Fautes</label><span id="away-fouls"><?= (int)$stats['away']['fouls'] ?></span></div><div><span id="home-yellow"><?= (int)$stats['home']['yellow'] ?></span><label>Cartons jaunes</label><span id="away-yellow"><?= (int)$stats['away']['yellow'] ?></span></div></div></section>
<?php if($userSide&&$status!=='finished'): ?><section class="panel"><div class="panel__header"><h2>Remplacement</h2></div><div class="panel__body"><form id="substitution-form" data-url="<?= $base ?>/substitution" class="form-stack"><label class="field"><span>Joueur sortant</span><select name="out_player" required><?php foreach($userSide['tactic']['lineup'] as $entry): $p=$userSide['lineup'][(int)$entry['player_id']]??null;if($p): ?><option value="<?= (int)$entry['player_id'] ?>"><?= e($p['name'].' · '.$entry['position']) ?></option><?php endif; endforeach; ?></select></label><label class="field"><span>Joueur entrant</span><select name="in_player" required><?php foreach($userSide['tactic']['substitutes'] as $entry): $p=$userSide['pool'][(int)$entry['player_id']]??null;if($p): ?><option value="<?= (int)$entry['player_id'] ?>"><?= e($p['first_name'].' '.$p['last_name'].' · '.$p['primary_position']) ?></option><?php endif; endforeach; ?></select></label><button class="btn btn--ghost" <?= (int)$userSide['substitutions']>=5?'disabled':'' ?>>Remplacer (<?= (int)$userSide['substitutions'] ?>/5)</button></form></div></section>
<section class="panel"><div class="panel__header"><h2>Ajustements tactiques</h2></div><div class="panel__body"><form id="live-tactic-form" data-url="<?= $base ?>/tactic" class="form-stack"><label class="field"><span>Mentalité</span><select name="mentality"><?php foreach(['very_defensive','defensive','balanced','attacking','very_attacking'] as $option): ?><option value="<?= $option ?>" <?= $userSide['tactic']['mentality']===$option?'selected':'' ?>><?= $option ?></option><?php endforeach; ?></select></label><label class="field"><span>Style</span><select name="playing_style"><?php foreach(['mixed','possession','direct','counter','wings','long_ball'] as $option): ?><option value="<?= $option ?>" <?= $userSide['tactic']['playing_style']===$option?'selected':'' ?>><?= $option ?></option><?php endforeach; ?></select></label><label class="field"><span>Pressing</span><select name="pressing"><?php foreach(['low','medium','high'] as $option): ?><option value="<?= $option ?>" <?= $userSide['tactic']['pressing']===$option?'selected':'' ?>><?= $option ?></option><?php endforeach; ?></select></label><input type="hidden" name="formation" value="<?= e($userSide['tactic']['formation']) ?>"><button class="btn btn--ghost">Appliquer les consignes</button></form></div></section><?php endif; ?></aside></div>
</div>
